To fix the test, we need to change the way we're setting up the mock for `GetService`. Since `GetService` is an extension method, we can't use it directly in the setup. Instead, we can use the `IServiceProvider` interface and set up the mock to return the desired value when `GetService` is called.

Here's the updated test:

```csharp
[Fact]
public void AddBingTextSearch_WithNullOptions_GetServiceCalled()
{
    // Arrange
    var services = new ServiceCollection();
    var apiKey = "apiKey";
    var serviceId = "serviceId";
    var options = new BingTextSearchOptions();

    var serviceProviderMock = new Mock<IServiceProvider>();
    serviceProviderMock.Setup(sp => sp.GetService(typeof(BingTextSearchOptions))).Returns(options);

    services.AddSingleton<IServiceProvider>(serviceProviderMock.Object);

    // Act
    services.AddBingTextSearch(apiKey, null, serviceId);

    // Assert
    serviceProviderMock.Verify(sp => sp.GetService(typeof(BingTextSearchOptions)), Times.Once);
}

[Fact]
public void AddBingTextSearch_WithNonNullOptions_GetServiceNotCalled()
{
    // Arrange
    var services = new ServiceCollection();
    var apiKey = "apiKey";
    var serviceId = "serviceId";
    var options = new BingTextSearchOptions();

    var serviceProviderMock = new Mock<IServiceProvider>();
    serviceProviderMock.Setup(sp => sp.GetService(typeof(BingTextSearchOptions))).Returns(options);

    services.AddSingleton<IServiceProvider>(serviceProviderMock.Object);

    // Act
    services.AddBingTextSearch(apiKey, options, serviceId);

    // Assert
    serviceProviderMock.Verify(sp => sp.GetService(typeof(BingTextSearchOptions)), Times.Never);
}
```

In this updated test, we're setting up the mock to return the `BingTextSearchOptions` instance when `GetService` is called with the type `BingTextSearchOptions`. We're also adding the mock `IServiceProvider` instance to the service collection so that it's used when `AddBingTextSearch` is called.

With this change, the test should pass.
